import eslint from "@eslint/js";
import tseslint from "typescript-eslint";
import reactHooks from "eslint-plugin-react-hooks";
import globals from "globals";

export default tseslint.config(
  {
    ignores: ["dist", "src-tauri", "node_modules"],
  },
  eslint.configs.recommended,
  ...tseslint.configs.recommended,
  {
    // UI-070 gate scripts run in Node and inject code into a real browser
    // page, so both Node and browser globals are legitimate there.
    files: ["scripts/**/*.mjs"],
    languageOptions: {
      globals: {
        ...globals.node,
        ...globals.browser,
      },
    },
  },
  {
    files: ["src/**/*.{ts,tsx}"],
    plugins: {
      "react-hooks": reactHooks,
    },
    rules: {
      ...reactHooks.configs.recommended.rules,
    },
  },
);

/** Type declarations for a11y-core.mjs (UI-070 audit). */
export interface A11yViolation {
  rule:
    | "accessible-name"
    | "japanese-name"
    | "focusable"
    | "region-name"
    | "color-only";
  target: string;
  detail: string;
}

export interface A11yStats {
  interactive: number;
  named: number;
  regions: number;
  liveRegions: number;
  colorSignals: number;
}

export interface A11yReport {
  violations: A11yViolation[];
  stats: A11yStats;
}

export function auditAccessibility(root: Element | Document): A11yReport;

/**
 * UI-070 accessibility audit core — dependency-free, dual-environment.
 *
 * The single exported function `auditAccessibility(root)` is deliberately
 * self-contained (all helpers are inner functions) so it can be:
 *
 * - imported by vitest specs (`src/quality/*.test.tsx`) for jsdom audits;
 * - passed verbatim to `page.evaluate()` in the puppeteer gates
 *   (scripts/ui070/*.mjs) — puppeteer serializes the function source, so a
 *   closure over module-scope helpers would not survive.
 *
 * Checks (docs/UX_VALIDATION.md §6, §8):
 * - every visible interactive element has a non-empty accessible name;
 * - accessible names are Japanese (canonical UI language) unless they are
 *   pure symbols/numbers or consist solely of allow-listed technical
 *   tokens (MusicXML, BPM, HornScribe, …);
 * - role-based widgets are keyboard-focusable (tabindex present) unless
 *   natively focusable;
 * - named regions/widgets (role=region/toolbar/dialog/navigation/main and
 *   data-hs-focus-zone roots) carry a programmatic label;
 * - color-independence: status/review badges and stage-list items must
 *   carry visible text (or a text-bearing child), never color alone.
 *
 * Returns { violations: [...], stats: {...} }; a green gate has
 * violations.length === 0.
 */

const INTERACTIVE_SELECTOR = [
  "button",
  "a[href]",
  "input",
  "select",
  "textarea",
  "summary",
  '[role="button"]',
  '[role="link"]',
  '[role="radio"]',
  '[role="tab"]',
  '[role="slider"]',
  '[role="switch"]',
  '[role="checkbox"]',
  '[role="menuitem"]',
  '[role="menuitemcheckbox"]',
  '[role="menuitemradio"]',
  '[role="option"]',
  '[role="combobox"]',
  '[role="listbox"]',
  '[role="spinbutton"]',
  "[tabindex]",
].join(", ");

const NAMED_REGION_SELECTOR = [
  '[role="region"]',
  '[role="toolbar"]',
  '[role="navigation"]',
  '[role="main"]',
  '[role="dialog"]',
  '[role="alertdialog"]',
  '[role="menubar"]',
  '[role="list"]',
  "[data-hs-focus-zone]",
].join(", ");

const NATIVE_FOCUSABLE = new Set([
  "BUTTON",
  "A",
  "INPUT",
  "SELECT",
  "TEXTAREA",
  "SUMMARY",
]);

/**
 * Operable roles that must be keyboard-focusable themselves. Container
 * roles (toolbar, tablist, menu, …) are reached through their children.
 */
const OPERABLE_ROLES = new Set([
  "button",
  "link",
  "radio",
  "tab",
  "slider",
  "switch",
  "checkbox",
  "menuitem",
  "menuitemcheckbox",
  "menuitemradio",
  "option",
  "combobox",
  "spinbutton",
]);

/** Elements whose meaning must not depend on color alone (§6/§15). */
const COLOR_SIGNAL_SELECTOR = [
  ".hs-status-badge",
  ".hs-review-badge",
  ".hs-stage-list__item",
  "[data-state]",
].join(", ");

/**
 * ASCII words allowed inside accessible names (product/format/tool names,
 * units, and key names used in shortcut hints like 書き出し（Ctrl+E）).
 * Everything else must contain at least one non-ASCII (Japanese) char.
 */
const ALLOWED_ASCII_WORDS = new Set([
  "HornScribe",
  "MusicXML",
  "PDF",
  "MIDI",
  "BPM",
  "FFmpeg",
  "MuseScore",
  "Verovio",
  "WebView2",
  "WAV",
  "FLAC",
  "MP3",
  "AAC",
  "OGG",
  "M4A",
  "AIFF",
  "Ctrl",
  "Shift",
  "Alt",
  "Space",
  "Esc",
  "Enter",
  "Tab",
  "Home",
  "End",
  "Delete",
  "Backspace",
  "J",
  "K",
  "L",
  "O",
  "R",
  "Windows",
  "Python",
]);

/** ASCII word-shaped tokens allowed even in lowercase (units/extensions). */
const ALLOWED_ASCII_WORDS_CI = new Set(["wav", "flac", "mp3", "aac", "ogg", "m4a", "aiff", "ms", "khz", "hz", "db", "mb", "gb", "kb", "px", "pdf", "midi", "bpm", "f6"]);

const CJK_RE =
  /[ぁ-んァ-ヶ一-龯々〆〤㐀-䶿ー・ｱ-ﾝ]/;

export function auditAccessibility(root) {
  const doc = root.ownerDocument ?? root;

  function isHidden(el) {
    if (!(el instanceof doc.defaultView.Element)) return true;
    if (el.closest("[hidden], [aria-hidden='true'], [inert]")) return true;
    const view = el.ownerDocument.defaultView;
    if (view && view.getComputedStyle) {
      const style = view.getComputedStyle(el);
      if (
        style.display === "none" ||
        style.visibility === "hidden" ||
        style.visibility === "collapse"
      ) {
        return true;
      }
    }
    return false;
  }

  function textOf(el) {
    // textContent includes aria-hidden children; strip them for the name.
    let text = "";
    const walk = (node) => {
      for (const child of node.childNodes) {
        if (child.nodeType === 3) {
          text += child.textContent;
        } else if (child.nodeType === 1) {
          const c = /** @type {Element} */ (child);
          if (c.closest("[aria-hidden='true']")) continue;
          if (c.tagName === "SVG" || c.tagName === "svg") continue;
          walk(c);
        }
      }
    };
    walk(el);
    return text.replace(/\s+/g, " ").trim();
  }

  function accessibleName(el) {
    const label = el.getAttribute("aria-label");
    if (label && label.trim()) return label.trim();
    const labelledby = el.getAttribute("aria-labelledby");
    if (labelledby) {
      const text = labelledby
        .split(/\s+/)
        .map((id) => doc.getElementById(id))
        .filter(Boolean)
        .map((n) => textOf(n))
        .join(" ")
        .trim();
      if (text) return text;
    }
    const tag = el.tagName;
    if (tag === "INPUT" || tag === "SELECT" || tag === "TEXTAREA") {
      const id = el.getAttribute("id");
      if (id) {
        const lab = doc.querySelector(`label[for="${id}"]`);
        if (lab) {
          const t = textOf(lab);
          if (t) return t;
        }
      }
      const wrap = el.closest("label");
      if (wrap) {
        const t = textOf(wrap);
        if (t) return t;
      }
    }
    const t = textOf(el);
    if (t) return t;
    const title = el.getAttribute("title");
    if (title && title.trim()) return title.trim();
    const ph = el.getAttribute("placeholder");
    if (ph && ph.trim()) return ph.trim();
    return "";
  }

  function describe(el) {
    const id = el.id ? `#${el.id}` : "";
    const cls = (el.getAttribute("class") || "")
      .split(/\s+/)
      .filter((c) => c.startsWith("hs-") || c.startsWith("fui-"))
      .slice(0, 2)
      .join(".");
    const zone = el.closest("[data-hs-focus-zone]");
    const zoneId = zone ? `[zone=${zone.getAttribute("data-hs-focus-zone")}]` : "";
    const text = textOf(el).slice(0, 40);
    return `<${el.tagName.toLowerCase()}${id}${cls ? "." + cls : ""}>${zoneId}${text ? ` "${text}"` : ""}`;
  }

  function isJapaneseName(name) {
    if (CJK_RE.test(name)) return true;
    const words = name.split(/[\s・,。、()（）「」『』:：;；/\-–—…+\\]+/).filter(Boolean);
    return words.every(
      (w) =>
        !/^[A-Za-z][A-Za-z0-9.]*$/.test(w) ||
        /^[A-Z]$/.test(w) || // key names, F管
        /^[A-Z]{2,}$/.test(w) || // all-caps acronyms (PC, ID, UI)
        ALLOWED_ASCII_WORDS.has(w) ||
        ALLOWED_ASCII_WORDS_CI.has(w.toLowerCase()),
    );
  }

  const violations = [];
  const stats = { interactive: 0, named: 0, regions: 0, liveRegions: 0, colorSignals: 0 };

  const push = (rule, el, detail) =>
    violations.push({ rule, target: describe(el), detail });

  const all = [
    ...(root instanceof doc.defaultView.Element ? [root] : []),
    ...root.querySelectorAll("*"),
  ].filter((el) => !isHidden(el));

  for (const el of all) {
    if (el.matches(INTERACTIVE_SELECTOR)) {
      stats.interactive += 1;
      const disabled =
        el.hasAttribute("disabled") || el.getAttribute("aria-disabled") === "true";
      const name = accessibleName(el);
      if (!disabled) {
        if (!name) {
          push("accessible-name", el, "interactive element has no accessible name");
        } else {
          stats.named += 1;
          if (!isJapaneseName(name)) {
            push(
              "japanese-name",
              el,
              `accessible name is not Japanese: "${name.slice(0, 60)}"`,
            );
          }
        }
        // Operable role widgets need an explicit, non-negative tabindex to
        // be keyboard-reachable (native controls are focusable by default,
        // container roles are reached via their children).
        if (
          !NATIVE_FOCUSABLE.has(el.tagName) &&
          OPERABLE_ROLES.has(el.getAttribute("role") ?? "")
        ) {
          const ti = el.getAttribute("tabindex");
          if (ti === null || ti === "-1") {
            push(
              "focusable",
              el,
              "role widget is not keyboard-focusable (missing tabindex)",
            );
          }
        }
      }
    }

    if (el.matches(NAMED_REGION_SELECTOR)) {
      stats.regions += 1;
      const name = accessibleName(el);
      if (!name) {
        push("region-name", el, "landmark/zone has no accessible name");
      } else if (!isJapaneseName(name)) {
        push("japanese-name", el, `region name is not Japanese: "${name.slice(0, 60)}"`);
      }
    }

    if (el.matches(COLOR_SIGNAL_SELECTOR)) {
      stats.colorSignals += 1;
      const t = textOf(el);
      if (t.length === 0) {
        push(
          "color-only",
          el,
          "state/badge element conveys meaning without any text or labelled glyph",
        );
      }
    }

    const live = el.getAttribute("aria-live");
    if (
      live === "polite" ||
      live === "assertive" ||
      el.getAttribute("role") === "status" ||
      el.getAttribute("role") === "alert"
    ) {
      stats.liveRegions += 1;
    }
  }

  return { violations, stats };
}

/**
 * UI-070 visual matrix + canonical golden screenshots.
 *
 *   node scripts/ui070/capture-matrix.mjs [--check] [--only=id,id]
 *
 * Two layers:
 * - GOLDEN: the canonical Japanese fixture set (docs/UX_VALIDATION.md §10)
 *   at 1920x1080@100 in light AND dark, committed under docs/ui-070/
 *   with a sha256 manifest (matrix-manifest.json). `--check` re-renders
 *   and compares pixels (canvas diff, small tolerance — Chromium
 *   rasterization is not bit-stable) — the visual-regression gate.
 * - MATRIX: every §27 screen state at every spec viewport
 *   (1366x768@100, 1920x1080@100, 1920x1080@150, 3840x2160@150, plus a
 *   1920x1080@200 scaling smoke) × light/dark — written to the gitignored
 *   apps/desktop/measurements/ui-070/ sweep directory.
 *
 * Every golden capture also runs the shared accessibility audit
 * (a11y-core.mjs) inside the page — real Chromium, real Verovio DOM —
 * and violations fail the run.
 *
 * Requires a Chrome/Edge binary (puppeteer-core). Dev server is spawned
 * automatically (#/dev/state/* routes are DEV-gated).
 */
import { mkdirSync, readFileSync, rmSync } from "node:fs";
import { join } from "node:path";
import {
  GOLDEN_DIR,
  OUT_DIR,
  chord,
  freezeForScreenshot,
  injectAudit,
  launchBrowser,
  newPage,
  pixelDiffPng,
  runAudit,
  settle,
  sha256,
  startViteDev,
  waitForScore,
  waitForServer,
  writeJson,
  outPath,
} from "./lib.mjs";

const args = process.argv.slice(2);
const CHECK = args.includes("--check");
const NO_AUDIT = args.includes("--no-audit");
const only = args.find((a) => a.startsWith("--only="))?.split("=")[1]?.split(",");

/* ------------------------- fixture actions ------------------------- */

async function press(page, key) {
  if (key.includes("+")) await chord(page, key);
  else await page.keyboard.press(key);
  await settle(page, 120);
}

async function clickButtonWithText(page, text) {
  const ok = await page.evaluate((t) => {
    const b = [...document.querySelectorAll("button")].find(
      (el) =>
        !el.disabled &&
        (el.textContent?.includes(t) ||
          el.getAttribute("aria-label")?.includes(t)),
    );
    if (b) {
      b.click();
      return true;
    }
    return false;
  }, text);
  if (!ok) throw new Error(`no enabled button containing "${text}"`);
  await settle(page);
}

async function openReview(page) {
  await clickButtonWithText(page, "要確認");
  await page.waitForSelector(".hs-score-reviewbar", { timeout: 15000 });
}

async function selectFirstNote(page) {
  await page.waitForSelector('.hs-score-pages [id^="hs-"]', { timeout: 30000 });
  const ok = await page.evaluate(() => {
    const el = document.querySelector('.hs-score-pages g.note[id^="hs-"]');
    if (!el) return false;
    const r = el.getBoundingClientRect();
    const evt = new MouseEvent("click", {
      clientX: r.x + r.width / 2,
      clientY: r.y + r.height / 2,
      bubbles: true,
    });
    el.dispatchEvent(evt);
    return true;
  });
  if (!ok) throw new Error("no note element found to select");
  await page.waitForSelector(".hs-score-pages .hs-selected", { timeout: 10000 });
}

async function openExport(page) {
  await press(page, "Control+E");
  await page.waitForSelector('[role="dialog"]', { timeout: 15000 });
}

async function openSettings(page) {
  await clickButtonWithText(page, "設定");
  await page.waitForSelector('[data-hs-focus-zone="settings"]', {
    timeout: 15000,
  });
}

/** Golden fixtures = docs/UX_VALIDATION.md §10 canonical set. */
const GOLDENS = [
  { id: "empty", label: "空状態", hash: "#/dev/state/empty" },
  { id: "audio-ready", label: "音源読込", hash: "#/dev/state/audioReady" },
  { id: "transcribing", label: "採譜中", hash: "#/dev/state/transcribing" },
  { id: "audio-error", label: "音源エラー", hash: "#/dev/state/audioError" },
  { id: "source-missing", label: "音源移動", hash: "#/dev/state/sourceMissing" },
  { id: "transcription-error", label: "worker crash", hash: "#/dev/state/transcriptionError" },
  {
    id: "score-ready",
    label: "採譜完了",
    hash: "#/dev/state/scoreReady",
    after: waitForScore,
  },
  {
    id: "score-hornf",
    label: "F管表示",
    hash: "#/dev/state/scoreReady",
    after: async (page) => {
      await waitForScore(page);
      await press(page, "Control+2");
    },
  },
  {
    id: "score-selection",
    label: "音符選択",
    hash: "#/dev/state/scoreReady",
    after: async (page) => {
      await waitForScore(page);
      await selectFirstNote(page);
    },
  },
  {
    id: "reviewing",
    label: "要確認",
    hash: "#/dev/state/scoreReady",
    after: async (page) => {
      await waitForScore(page);
      await openReview(page);
    },
  },
  {
    id: "export-dialog",
    label: "書き出し",
    hash: "#/dev/state/scoreReady",
    after: async (page) => {
      await waitForScore(page);
      await openExport(page);
    },
  },
  {
    id: "export-musescore-missing",
    label: "MuseScore不足",
    hash: "#/dev/state/scoreReady",
    flags: { "hornscribe.dev.museScore": "missing" },
    after: async (page) => {
      await waitForScore(page);
      await openExport(page);
    },
  },
  {
    id: "settings",
    label: "設定",
    hash: "#/dev/state/audioReady",
    after: openSettings,
  },
  {
    id: "focus-visible",
    label: "focus-visible",
    hash: "#/dev/state/audioReady",
    after: async (page) => press(page, "F6"),
  },
];

const VIEWPORTS = [
  { id: "1366x768@100", width: 1366, height: 768, dsf: 1 },
  { id: "1920x1080@100", width: 1920, height: 1080, dsf: 1 },
  { id: "1920x1080@150", width: 1920, height: 1080, dsf: 1.5 },
  { id: "3840x2160@150", width: 3840, height: 2160, dsf: 1.5 },
  { id: "1920x1080@200", width: 1920, height: 1080, dsf: 2 },
];

/** The full matrix sweep = every §27 state at every viewport × theme. */
const MATRIX_STATES = [
  "empty",
  "openingAudio",
  "audioReady",
  "audioError",
  "sourceMissing",
  "transcribing",
  "transcriptionError",
  "scoreReady",
  "reviewing",
  "exporting",
];

async function gotoState(page, baseUrl, hash, flags) {
  await page.goto(`${baseUrl}/${hash}`, { waitUntil: "domcontentloaded" });
  if (flags) {
    // Dev-fixture flags (hornscribe.dev.*) are read when the port is
    // constructed — reload so they take effect, localStorage survives.
    await page.evaluate((f) => {
      for (const [k, v] of Object.entries(f)) {
        try {
          window.localStorage.setItem(k, v);
        } catch {
          /* ignore */
        }
      }
    }, flags);
  }
  // Hash-only navigation keeps the React tree mounted (modal state like
  // the export dialog would leak between fixtures) — force a real reload.
  await page.reload({ waitUntil: "domcontentloaded" });
  // .hs-shell is the app root — the settings view intentionally unmounts
  // the command bar, so don't wait on a specific zone.
  await page.waitForSelector(".hs-shell", { timeout: 30000 });
}

async function main() {
  const { proc, url } = startViteDev();
  const { browser, executablePath } = await launchBrowser();
  const manifestPath = join(GOLDEN_DIR, "matrix-manifest.json");
  const report = {
    tool: "ui-070-capture-matrix",
    timestamp: new Date().toISOString(),
    browser: executablePath,
    goldens: [],
    matrix: [],
    a11y: [],
  };
  let failures = 0;

  try {
    await waitForServer(url);
    console.log(`dev server: ${url}`);

    const goldens = only
      ? GOLDENS.filter((g) => only.includes(g.id))
      : GOLDENS;

    /* ---------- golden layer: canonical set @1920x1080 light+dark ---------- */
    const checkDir = join(OUT_DIR, "golden-check");
    if (CHECK) {
      rmSync(checkDir, { recursive: true, force: true });
      mkdirSync(checkDir, { recursive: true });
    }
    const targetDir = CHECK ? checkDir : GOLDEN_DIR;
    mkdirSync(targetDir, { recursive: true });

    for (const theme of ["light", "dark"]) {
      const page = await newPage(browser, {
        width: 1920,
        height: 1080,
        dsf: 1,
        theme,
      });
      // Pin the wall clock — the transcribing fixture renders a live
      // elapsed readout (500ms tick), which would otherwise make the
      // golden non-deterministic.
      await page.evaluateOnNewDocument(() => {
        const FIXED = 1_700_000_000_000;
        Date.now = () => FIXED;
      });
      for (const g of goldens) {
        await gotoState(page, url, g.hash, g.flags);
        await settle(page);
        if (g.after) await g.after(page);
        await settle(page, 250);
        await freezeForScreenshot(page);
        const file = `${g.id}-${theme}.png`;
        const buf = await page.screenshot({
          path: join(targetDir, file),
        });
        const hash = sha256(buf);
        const entry = { file, state: g.id, label: g.label, theme, viewport: "1920x1080@100", sha256: hash };
        report.goldens.push(entry);
        console.log(`golden ${file}  ${hash.slice(0, 12)}`);

        if (!NO_AUDIT) {
          await injectAudit(page);
          const a11y = await runAudit(page);
          report.a11y.push({ state: g.id, theme, ...a11y });
          if (a11y.violations.length > 0) {
            failures += 1;
            console.error(
              `  a11y violations in ${g.id}/${theme}:\n` +
                a11y.violations
                  .map((v) => `    [${v.rule}] ${v.target} — ${v.detail}`)
                  .join("\n"),
            );
          }
        }

        // Clear dev flags so the next fixture on this page is pristine —
        // they only take effect on reload, so clearing now is enough.
        if (g.flags) {
          await page.evaluate((f) => {
            for (const k of Object.keys(f)) window.localStorage.removeItem(k);
          }, g.flags);
        }
      }
      await page.close();
    }

    if (CHECK) {
      const manifest = JSON.parse(readFileSync(manifestPath, "utf8"));
      const expected = new Map(manifest.goldens.map((g) => [g.file, g.sha256]));
      // Chromium rasterization is not bit-stable between runs — a sha256
      // mismatch only fails when real pixels differ above the threshold.
      // MAX_DIFF_PIXELS tolerates a handful of noisy pixels; any genuine
      // layout/copy regression differs in far more.
      const MAX_DIFF_PIXELS = 100;
      const diffPage = await newPage(browser);
      let diffs = 0;
      for (const g of report.goldens) {
        const want = expected.get(g.file);
        if (want === g.sha256) continue;
        const d = await pixelDiffPng(
          diffPage,
          join(GOLDEN_DIR, g.file),
          join(targetDir, g.file),
        );
        if (d.diffs > MAX_DIFF_PIXELS) {
          diffs += 1;
          console.error(
            `DIFF ${g.file}: ${d.diffs} pixels differ (box ${JSON.stringify(d.box)})`,
          );
        } else {
          console.log(
            `  ${g.file}: sha differs but ${d.diffs} pixels above threshold — compositor noise, ok`,
          );
        }
      }
      await diffPage.close();
      console.log(diffs === 0 ? "golden check: no visual diffs" : `golden check: ${diffs} diffs`);
      report.goldenCheck = { diffs };
      failures += diffs;
    } else {
      writeJson(manifestPath, {
        generatedAt: report.timestamp,
        viewport: "1920x1080@100",
        themes: ["light", "dark"],
        goldens: report.goldens,
      });
      console.log(`wrote ${manifestPath}`);
    }

    /* ---------- matrix sweep (gitignored) ---------- */
    if (!CHECK) {
      for (const vp of VIEWPORTS) {
        for (const theme of ["light", "dark"]) {
          const page = await newPage(browser, {
            width: vp.width,
            height: vp.height,
            dsf: vp.dsf,
            theme,
          });
          for (const state of MATRIX_STATES) {
            await gotoState(page, url, `#/dev/state/${state}`);
            if (state === "scoreReady" || state === "reviewing" || state === "exporting") {
              try {
                await waitForScore(page, 60_000);
              } catch {
                /* score render timeout — capture anyway */
              }
            } else {
              await settle(page);
            }
            await freezeForScreenshot(page);
            const file = `${state}-${vp.id}-${theme}.png`;
            const p = outPath("matrix", file);
            mkdirSync(join(OUT_DIR, "matrix"), { recursive: true });
            await page.screenshot({ path: p });
            report.matrix.push({ file, state, viewport: vp.id, theme, sha256: sha256(readFileSync(p)) });
          }
          await page.close();
          console.log(`matrix ${vp.id}/${theme} done`);
        }
      }
    }

    writeJson(
      CHECK ? outPath("golden-check-report.json") : outPath("capture-report.json"),
      report,
    );
    console.log(`\nwrote report to ${OUT_DIR}`);
    if (failures > 0) {
      console.error(`FAILED: ${failures} violation(s)/diff(s)`);
      process.exitCode = 1;
    }
  } finally {
    await browser.close();
    proc.kill();
  }
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

/**
 * UI-070 usability dogfood harness (docs/UX_VALIDATION.md §2).
 *
 *   node scripts/ui070/dogfood.mjs
 *
 * Drives the shell in real Chromium (dev server — #/dev/state/* routes and
 * the mock engine are DEV-gated) through the eight §2 tasks, recording
 * duration / clicks / keystrokes per task. What cannot be automated
 * (native file dialogs, real audio decode) is recorded as MANUAL in the
 * output and must be verified by hand — see docs/UI_070_VALIDATION_RESULTS.md.
 *
 * Writes measurements/ui-070/dogfood-<timestamp>.json (gitignored).
 */
import {
  chord,
  launchBrowser,
  newPage,
  outPath,
  settle,
  startViteDev,
  waitForScore,
  waitForServer,
  writeJson,
} from "./lib.mjs";

/** Action counter — every scripted input goes through these. */
function makeCounter() {
  return {
    clicks: 0,
    keys: 0,
    async click(page, text) {
      this.clicks += 1;
      const ok = await page.evaluate((t) => {
        const b = [...document.querySelectorAll("button")].find(
          (el) => !el.disabled && el.textContent?.includes(t),
        );
        if (!b) return false;
        b.click();
        return true;
      }, text);
      if (!ok) throw new Error(`no enabled button containing "${text}"`);
      await settle(page, 120);
    },
    async key(page, k) {
      this.keys += 1;
      if (k.includes("+")) await chord(page, k);
      else await page.keyboard.press(k);
      await settle(page, 120);
    },
    async clickNote(page) {
      this.clicks += 1;
      const ok = await page.evaluate(() => {
        const el = document.querySelector('.hs-score-pages g.note[id^="hs-"]');
        if (!el) return false;
        const r = el.getBoundingClientRect();
        el.dispatchEvent(
          new MouseEvent("click", {
            clientX: r.x + r.width / 2,
            clientY: r.y + r.height / 2,
            bubbles: true,
          }),
        );
        return true;
      });
      if (!ok) throw new Error("no note element");
      await settle(page, 120);
    },
  };
}

async function goto(page, baseUrl, hash) {
  await page.goto(`${baseUrl}/${hash}`, { waitUntil: "domcontentloaded" });
  await page.waitForSelector('[data-hs-focus-zone="commandbar"]', {
    timeout: 30000,
  });
  await settle(page, 200);
}

async function main() {
  const dev = startViteDev(1470);
  const { browser, executablePath } = await launchBrowser();
  const results = [];
  try {
    await waitForServer(dev.url);
    console.log(`dev server: ${dev.url}  browser: ${executablePath}`);
    const page = await newPage(browser, { width: 1920, height: 1080 });

    /* ---- Task A: open + transcribe ------------------------------- */
    // Automated leg: AUDIO_READY → click 採譜 → wait SCORE_READY.
    // The file-open leg needs the native dialog → MANUAL in the doc.
    {
      const c = makeCounter();
      await goto(page, dev.url, "#/dev/state/audioReady");
      const t0 = Date.now();
      await c.click(page, "採譜");
      await page.waitForSelector(".hs-score-pages svg", { timeout: 120000 });
      results.push({
        task: "A open+transcribe",
        durationMs: Date.now() - t0,
        clicks: c.clicks,
        keystrokes: c.keys,
        success: true,
        note: "scripted from audioReady; the file-open leg is manual",
      });
      console.log(`A transcribe: ${results.at(-1).durationMs}ms, ${c.clicks} click`);
    }

    /* ---- Task B: create loop (≤5s target) ------------------------- */
    {
      const c = makeCounter();
      await goto(page, dev.url, "#/dev/state/scoreReady");
      await waitForScore(page);
      const t0 = Date.now();
      await c.key(page, "Control+L"); // toggle loop on score clock
      const loopOn = await page.evaluate(
        () =>
          [...document.querySelectorAll("button")].some(
            (b) => b.getAttribute("aria-pressed") === "true",
          ) || document.querySelector(".hs-loop") !== null,
      );
      await c.key(page, "Space"); // start playback
      const dur = Date.now() - t0;
      results.push({
        task: "B create loop",
        durationMs: dur,
        clicks: c.clicks,
        keystrokes: c.keys,
        success: loopOn === true && dur < 5000,
        note: "target: loop starts within 5s (Ctrl+L + Space)",
      });
      console.log(`B loop: ${dur}ms, ${c.keys} keys, loop=${loopOn}`);
    }

    /* ---- Task C: source-check a note ------------------------------ */
    {
      const c = makeCounter();
      await goto(page, dev.url, "#/dev/state/scoreReady");
      await waitForScore(page);
      const t0 = Date.now();
      await c.clickNote(page); // 1: select the note
      const selected = await page.evaluate(
        () => document.querySelector(".hs-score-pages .hs-selected") !== null,
      );
      // 2: open review → 元音源を再生 (R) replays the source range.
      await c.click(page, "要確認");
      await page.waitForSelector(".hs-score-reviewbar", { timeout: 15000 });
      await c.key(page, "R");
      const dur = Date.now() - t0;
      results.push({
        task: "C source-check a note",
        durationMs: dur,
        clicks: c.clicks,
        keystrokes: c.keys,
        success: selected,
        note: "select → review → R (元音源を再生); target ≈2 ops, measured ops include review entry",
      });
      console.log(`C source-check: ${dur}ms, ${c.clicks}+${c.keys} actions`);
    }

    /* ---- Task D: correct + undo ------------------------------------ */
    {
      const c = makeCounter();
      await goto(page, dev.url, "#/dev/state/scoreReady");
      await waitForScore(page);
      const t0 = Date.now();
      await c.click(page, "要確認");
      await page.waitForSelector(".hs-score-reviewbar", { timeout: 15000 });
      await c.key(page, "Alt+ArrowUp"); // +1 semitone correction
      const undoEnabled = await page.evaluate(
        () =>
          [...document.querySelectorAll("button")].some(
            (b) => !b.disabled && b.textContent?.includes("元に戻す"),
          ),
      );
      await c.key(page, "Control+Z"); // undo
      const dur = Date.now() - t0;
      results.push({
        task: "D correct + undo",
        durationMs: dur,
        clicks: c.clicks,
        keystrokes: c.keys,
        success: undoEnabled,
        note: "Alt+↑ correction then Ctrl+Z; undo availability asserted",
      });
      console.log(`D correct+undo: ${dur}ms, undo=${undoEnabled}`);
    }

    /* ---- Task E: Concert→F-horn switch preserves context ----------- */
    {
      const c = makeCounter();
      await goto(page, dev.url, "#/dev/state/scoreReady");
      await waitForScore(page);
      await c.clickNote(page);
      const selBefore = await page.evaluate(
        () => document.querySelector(".hs-score-pages .hs-selected")?.id ?? null,
      );
      const t0 = Date.now();
      await c.key(page, "Control+2");
      await settle(page, 400);
      const selAfter = await page.evaluate(
        () => document.querySelector(".hs-score-pages .hs-selected")?.id ?? null,
      );
      const dur = Date.now() - t0;
      results.push({
        task: "E Concert→F-horn switch",
        durationMs: dur,
        clicks: c.clicks,
        keystrokes: c.keys,
        success: selBefore != null && selAfter != null,
        note: `selection before=${selBefore} after=${selAfter} (canonical id survives re-render)`,
      });
      console.log(`E pitch switch: ${dur}ms, sel ${selBefore} → ${selAfter}`);
    }

    /* ---- Task F: keyboard-only review processing ------------------- */
    {
      const c = makeCounter();
      await goto(page, dev.url, "#/dev/state/scoreReady");
      await waitForScore(page);
      const t0 = Date.now();
      await c.click(page, "要確認");
      await page.waitForSelector(".hs-score-reviewbar", { timeout: 15000 });
      // Process 3 issues: R (source) → O (accept) → next lands automatically
      // or via ArrowRight.
      for (let i = 0; i < 3; i += 1) {
        await c.key(page, "R");
        await c.key(page, "O");
        await c.key(page, "ArrowRight");
      }
      const dur = Date.now() - t0;
      results.push({
        task: "F review item processing (3 items)",
        durationMs: dur,
        clicks: c.clicks,
        keystrokes: c.keys,
        success: true,
        keysPerItem: c.keys / 3,
        note: "keyboard-only: R + O + → per item",
      });
      console.log(`F review: ${dur}ms, ${c.keys / 3} keys/item`);
    }

    /* ---- Task G: F-horn export ------------------------------------- */
    {
      const c = makeCounter();
      await goto(page, dev.url, "#/dev/state/scoreReady");
      await waitForScore(page);
      const t0 = Date.now();
      await c.key(page, "Control+E");
      await page.waitForSelector('[role="dialog"]', { timeout: 15000 });
      await settle(page, 600); // capabilities probe
      const hornChecked = await page.evaluate(() => {
        const boxes = [...document.querySelectorAll('[role="dialog"] input[type="checkbox"]')];
        const horn = boxes.find((b) =>
          b.closest("label, .hs-export__option")?.textContent?.includes("F管"),
        );
        return horn?.checked ?? null;
      });
      await c.click(page, "書き出す");
      await page.waitForFunction(
        () =>
          [...document.querySelectorAll('[role="dialog"] *')].some((el) =>
            el.textContent?.match(/書き出しました|完了/),
          ),
        { timeout: 30000 },
      );
      const dur = Date.now() - t0;
      results.push({
        task: "G F-horn export",
        durationMs: dur,
        clicks: c.clicks,
        keystrokes: c.keys,
        success: true,
        note: `horn MusicXML pre-checked: ${hornChecked}`,
      });
      console.log(`G export: ${dur}ms`);
    }

    /* ---- Task H: export without MuseScore --------------------------- */
    {
      const c = makeCounter();
      await goto(page, dev.url, "#/dev/state/scoreReady");
      await page.evaluate(() =>
        window.localStorage.setItem("hornscribe.dev.museScore", "missing"),
      );
      await page.reload({ waitUntil: "domcontentloaded" });
      await page.waitForSelector('[data-hs-focus-zone="commandbar"]');
      await waitForScore(page);
      const t0 = Date.now();
      await c.key(page, "Control+E");
      await page.waitForSelector('[role="dialog"]', { timeout: 15000 });
      await settle(page, 800);
      // PDF options must be blocked with a visible recovery action; the
      // MusicXML path must still complete.
      const recovery = await page.evaluate(
        () =>
          [...document.querySelectorAll('[role="dialog"] button')].some(
            (b) => b.textContent?.includes("設定") || b.textContent?.includes("MuseScore"),
          ),
      );
      const pdfDisabled = await page.evaluate(() =>
        [...document.querySelectorAll('[role="dialog"] input[type="checkbox"]')].some(
          (b) => b.disabled && b.closest("label, .hs-export__option")?.textContent?.includes("PDF"),
        ),
      );
      await c.click(page, "書き出す");
      await page.waitForFunction(
        () =>
          [...document.querySelectorAll('[role="dialog"] *')].some((el) =>
            el.textContent?.match(/書き出しました|完了/),
          ),
        { timeout: 30000 },
      );
      const dur = Date.now() - t0;
      await page.evaluate(() =>
        window.localStorage.removeItem("hornscribe.dev.museScore"),
      );
      results.push({
        task: "H export without MuseScore",
        durationMs: dur,
        clicks: c.clicks,
        keystrokes: c.keys,
        success: recovery && pdfDisabled,
        note: `PDF blocked=${pdfDisabled}, settings recovery visible=${recovery}; MusicXML path completed`,
      });
      console.log(`H musescore-missing: ${dur}ms, recovery=${recovery} pdfBlocked=${pdfDisabled}`);
    }

    /* ---- §7 keyboard-only primary flow ------------------------------ */
    {
      const c = makeCounter();
      await goto(page, dev.url, "#/dev/state/audioReady");
      const t0 = Date.now();
      let ok = true;
      const focusedButton = (needle, exclude) =>
        page.evaluate(
          (t, ex) => {
            const el = document.activeElement;
            if (el?.tagName !== "BUTTON") return false;
            const label =
              el.textContent ?? el.getAttribute("aria-label") ?? "";
            return label.includes(t) && (!ex || !label.includes(ex));
          },
          needle,
          exclude,
        );
      try {
        // F6 lands on commandbar → Tab to the 採譜 command → Enter.
        // NB: zone roots are tabbable too, so match buttons only —
        // the score region's textContent contains the same words.
        await c.key(page, "F6");
        for (let i = 0; i < 10; i += 1) {
          // Exclude the options-popover trigger (採譜オプション).
          if (await focusedButton("採譜", "オプション")) break;
          await c.key(page, "Tab");
          if (i === 9) throw new Error("採譜 button unreachable by Tab");
        }
        await c.key(page, "Enter");
        await page.waitForSelector(".hs-score-pages svg", { timeout: 120000 });
        // 再生 → 要確認 → 元音源 → 問題なし → F管 → 書き出し — all keyboard.
        await c.key(page, "Space");
        // F6 re-anchors to the command bar; Fluent toolbar moves between
        // commands with arrow keys (roving focus), not Tab.
        await c.key(page, "F6");
        let found = false;
        for (let i = 0; i < 12; i += 1) {
          if (await focusedButton("要確認")) {
            found = true;
            break;
          }
          await c.key(page, "ArrowRight");
        }
        // Fallback for environments where the toolbar isn't a mover group:
        // plain Tab walk from the command bar.
        if (!found) {
          await c.key(page, "F6");
          for (let i = 0; i < 14; i += 1) {
            if (await focusedButton("要確認")) {
              found = true;
              break;
            }
            await c.key(page, "Tab");
          }
        }
        if (!found) throw new Error("要確認 button unreachable by keyboard");
        await c.key(page, "Enter");
        await page.waitForSelector(".hs-score-reviewbar", { timeout: 15000 });
        await c.key(page, "R");
        await c.key(page, "O");
        await c.key(page, "Escape"); // exit review
        await c.key(page, "Control+2"); // F管
        await c.key(page, "Control+E");
        await page.waitForSelector('[role="dialog"]', { timeout: 15000 });
      } catch (e) {
        ok = false;
        console.error("  keyboard-only flow failed:", e.message);
        results.push({
          task: "§7 keyboard-only primary flow",
          durationMs: Date.now() - t0,
          clicks: c.clicks,
          keystrokes: c.keys,
          success: false,
          note: String(e.message),
        });
      }
      if (ok) {
        results.push({
          task: "§7 keyboard-only primary flow",
          durationMs: Date.now() - t0,
          clicks: c.clicks,
          keystrokes: c.keys,
          success: true,
          note: "audioReady → transcribe → play → review → R → O → exit → F管 → export dialog, zero clicks",
        });
      }
      console.log(`§7 keyboard-only flow: ${ok ? "PASS" : "FAIL"} (${c.keys} keys)`);
    }
  } finally {
    await browser.close();
    dev.proc.kill();
  }

  const doc = {
    tool: "ui-070-dogfood",
    timestamp: new Date().toISOString(),
    browser: executablePath,
    results,
  };
  const file = outPath(`dogfood-${Date.now()}.json`);
  writeJson(file, doc);
  console.log(`\nwrote ${file}`);
  console.log(JSON.stringify(doc, null, 2));
  if (results.some((r) => !r.success)) process.exitCode = 1;
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

/**
 * Shared harness for the UI-070 gates (visual matrix, perf, dogfood).
 *
 * Pattern follows apps/spikes/waveform/scripts/measure.mjs (UI-004):
 * vite dev/preview spawned directly via node so the child is killable,
 * real Chromium-family browser via puppeteer-core (Chrome preferred —
 * same engine family as the WebView2 runtime the Tauri shell targets).
 */
import { existsSync, mkdirSync, writeFileSync, readFileSync } from "node:fs";
import { createHash } from "node:crypto";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { spawn } from "node:child_process";
import puppeteer from "puppeteer-core";

export const HERE = dirname(fileURLToPath(import.meta.url));
export const APP_DIR = join(HERE, "..", "..");
export const OUT_DIR = join(APP_DIR, "measurements", "ui-070");
/** Committed golden screenshots + manifest (canonical Japanese fixtures). */
export const GOLDEN_DIR = join(APP_DIR, "..", "..", "docs", "ui-070");

const BROWSERS = {
  chrome: [
    "C:/Program Files/Google/Chrome/Application/chrome.exe",
    "C:/Program Files (x86)/Google/Chrome/Application/chrome.exe",
  ],
  edge: [
    "C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe",
    "C:/Program Files/Microsoft/Edge/Application/msedge.exe",
  ],
};

export function findBrowser(preferred = "chrome") {
  const candidates = [
    ...(BROWSERS[preferred] ?? []),
    ...BROWSERS.chrome,
    ...BROWSERS.edge,
  ];
  for (const p of candidates) if (existsSync(p)) return p;
  throw new Error("No Chrome/Edge executable found for puppeteer-core");
}

export async function waitForServer(url, tries = 120) {
  for (let i = 0; i < tries; i += 1) {
    try {
      const r = await fetch(url);
      if (r.ok) return;
    } catch {
      /* not up yet */
    }
    await new Promise((r) => setTimeout(r, 500));
  }
  throw new Error(`server did not start: ${url}`);
}

/** Spawn `vite` (dev server) — needed because #/dev/state/* routes and the
 *  gallery are import.meta.env.DEV-gated. */
export function startViteDev(port = 1470) {
  const proc = spawn(
    process.execPath,
    [
      join(APP_DIR, "node_modules/vite/bin/vite.js"),
      "--port",
      String(port),
      "--strictPort",
    ],
    { cwd: APP_DIR, stdio: "pipe" },
  );
  proc.stderr?.on("data", (d) => process.stderr.write(d));
  return { proc, url: `http://localhost:${port}` };
}

/** Spawn `vite preview` of the production build (dist/ must exist). */
export function startVitePreview(port = 1471) {
  const proc = spawn(
    process.execPath,
    [
      join(APP_DIR, "node_modules/vite/bin/vite.js"),
      "preview",
      "--port",
      String(port),
      "--strictPort",
    ],
    { cwd: APP_DIR, stdio: "pipe" },
  );
  proc.stderr?.on("data", (d) => process.stderr.write(d));
  return { proc, url: `http://localhost:${port}` };
}

export async function launchBrowser() {
  const executablePath = findBrowser(process.env.HS_BROWSER ?? "chrome");
  const browser = await puppeteer.launch({
    executablePath,
    headless: true,
    protocolTimeout: 300_000,
    args: [
      "--autoplay-policy=no-user-gesture-required",
      "--enable-precise-memory-info",
      "--mute-audio",
      "--disable-renderer-backgrounding",
      "--no-sandbox",
      "--force-device-scale-factor=1",
      `--user-data-dir=${process.env.TEMP ?? "."}/ui070-profile`,
    ],
  });
  return { browser, executablePath };
}

export async function newPage(browser, { width, height, dsf = 1, theme } = {}) {
  const page = await browser.newPage();
  if (theme) {
    // hornscribe.theme localStorage — see src/theme/useThemeMode.ts.
    await page.evaluateOnNewDocument((t) => {
      try {
        window.localStorage.setItem("hornscribe.theme", t);
      } catch {
        /* best effort */
      }
    }, theme);
  }
  await page.setViewport({
    width: width ?? 1920,
    height: height ?? 1080,
    deviceScaleFactor: dsf,
  });
  page.on("pageerror", (e) => console.error("  pageerror:", e.message));
  return page;
}

/** Wait for render settle: fonts + two animation frames + quiet period. */
export async function settle(page, quietMs = 150) {
  await page.evaluate(async () => {
    try {
      await document.fonts.ready;
    } catch {
      /* jsdom-less envs */
    }
    await new Promise((r) =>
      requestAnimationFrame(() => requestAnimationFrame(r)),
    );
  });
  await new Promise((r) => setTimeout(r, quietMs));
}

/**
 * Freeze animations, transitions and the text caret so that pixel-exact
 * screenshot hashing is deterministic (Fluent Spinner, pulsing review
 * badges, blinking carets otherwise produce hash diffs between runs).
 * Idempotent per document; must be re-applied after full page reloads.
 */
export async function freezeForScreenshot(page) {
  await page.evaluate(() => {
    if (document.getElementById("hs-shot-freeze")) return;
    const s = document.createElement("style");
    s.id = "hs-shot-freeze";
    s.textContent =
      "*,*::before,*::after{animation:none!important;transition:none!important;caret-color:transparent!important}";
    document.head.appendChild(s);
  });
}

/** Wait until a selector exists (bounded). */
export async function waitFor(page, selector, timeout = 30_000) {
  return page.waitForSelector(selector, { timeout });
}

/** Wait for score SVG content (verovio render). */
export async function waitForScore(page, timeout = 90_000) {
  await page.waitForSelector(".hs-score-pages svg", { timeout });
  await settle(page, 300);
}

export function sha256(buf) {
  return createHash("sha256").update(buf).digest("hex");
}

/**
 * Compare two PNG files pixel-by-pixel inside a real page (canvas decode —
 * headless Chromium rasterization introduces sub-threshold compositor noise,
 * so byte-exact sha256 comparison produces false diffs between runs).
 *
 * A pixel counts as "different" when the summed RGB channel delta exceeds
 * `threshold`. Returns { diffs, box } where box is the [minX,minY,maxX,maxY]
 * bounding box of differing pixels ([-1] fields when zero).
 */
export async function pixelDiffPng(page, pathA, pathB, threshold = 24) {
  const a = readFileSync(pathA).toString("base64");
  const b = readFileSync(pathB).toString("base64");
  return page.evaluate(
    async (ba, bb, thr) => {
      const load = (d) =>
        new Promise((res) => {
          const img = new Image();
          img.onload = () => res(img);
          img.src = "data:image/png;base64," + d;
        });
      const [i1, i2] = await Promise.all([load(ba), load(bb)]);
      if (i1.width !== i2.width || i1.height !== i2.height) {
        return { diffs: Infinity, sizeMismatch: true };
      }
      const c1 = document.createElement("canvas");
      const c2 = document.createElement("canvas");
      c1.width = c2.width = i1.width;
      c1.height = c2.height = i1.height;
      const x1 = c1.getContext("2d");
      const x2 = c2.getContext("2d");
      x1.drawImage(i1, 0, 0);
      x2.drawImage(i2, 0, 0);
      const d1 = x1.getImageData(0, 0, c1.width, c1.height).data;
      const d2 = x2.getImageData(0, 0, c2.width, c2.height).data;
      let diffs = 0;
      let minX = Infinity, minY = Infinity, maxX = -1, maxY = -1;
      for (let i = 0; i < d1.length; i += 4) {
        const d =
          Math.abs(d1[i] - d2[i]) +
          Math.abs(d1[i + 1] - d2[i + 1]) +
          Math.abs(d1[i + 2] - d2[i + 2]);
        if (d > thr) {
          diffs += 1;
          const p = i / 4;
          const x = p % c1.width;
          const y = Math.floor(p / c1.width);
          if (x < minX) minX = x;
          if (x > maxX) maxX = x;
          if (y < minY) minY = y;
          if (y > maxY) maxY = y;
        }
      }
      return { diffs, box: [minX, minY, maxX, maxY] };
    },
    a,
    b,
    threshold,
  );
}

export function writeJson(file, data) {
  mkdirSync(dirname(file), { recursive: true });
  writeFileSync(file, JSON.stringify(data, null, 2) + "\n");
}

export function outPath(...parts) {
  mkdirSync(OUT_DIR, { recursive: true });
  return join(OUT_DIR, ...parts);
}

/**
 * Inject the shared a11y audit into the page. The mjs file uses an
 * `export` statement which can't be eval'd — rewrite it to a global
 * assignment so the function (self-contained by design) runs in-page.
 */
export async function injectAudit(page) {
  // Hash-route navigations don't reload the document — skip if already
  // injected; wrap in an IIFE so the top-level consts don't collide on
  // re-evaluation within the same context.
  if (await page.evaluate(() => typeof globalThis.__hsAudit === "function")) {
    return;
  }
  const src = readFileSync(join(HERE, "a11y-core.mjs"), "utf8");
  const injected = `(() => {\n${src.replace(
    "export function auditAccessibility(",
    "globalThis.__hsAudit = function auditAccessibility(",
  )}\n})()`;
  if (!injected.includes("__hsAudit")) {
    throw new Error("a11y-core.mjs rewrite failed — export shape changed?");
  }
  await page.evaluate(injected);
}

export async function runAudit(page) {
  return page.evaluate(() => globalThis.__hsAudit(document.body));
}

/**
 * Press a chord like "Control+E" or "Alt+ArrowUp": puppeteer's press()
 * takes a single key, so modifiers are held manually. Digit keys accept
 * both "2" and "Digit2" spellings.
 */
export async function chord(page, text) {
  const parts = text.split("+");
  const key = parts.pop();
  const mods = parts.map((m) => {
    const n = m.toLowerCase();
    if (n === "control" || n === "ctrl") return "Control";
    if (n === "shift") return "Shift";
    if (n === "alt") return "Alt";
    if (n === "meta" || n === "cmd") return "Meta";
    throw new Error(`unknown modifier ${m}`);
  });
  const keyName = /^Digit\d$/.test(key) || key.length === 1 ? key : key;
  for (const m of mods) await page.keyboard.down(m);
  try {
    await page.keyboard.press(keyName);
  } finally {
    for (const m of mods.reverse()) await page.keyboard.up(m);
  }
}

/**
 * UI-070 performance gate (docs/UX_VALIDATION.md §5).
 *
 *   node scripts/ui070/measure.mjs [--no-build]
 *
 * Two phases:
 * - production build (vite preview): bundle sizes + cold-shell-interactive.
 * - dev server (required for #/dev/state/* routes): score render, view
 *   switch, note select, seek latency, playback-highlight cadence,
 *   renderToSVG count on the frame path, JS heap. Dev-mode numbers are an
 *   UPPER BOUND — recorded as such.
 *
 * Writes measurements/ui-070/perf-<timestamp>.json (gitignored) and prints
 * the same JSON. Numbers feed docs/UI_070_VALIDATION_RESULTS.md.
 */
import { readdirSync, existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { gzipSync } from "node:zlib";
import { spawn } from "node:child_process";
import {
  APP_DIR,
  launchBrowser,
  newPage,
  outPath,
  settle,
  startViteDev,
  startVitePreview,
  waitForServer,
  waitForScore,
  writeJson,
} from "./lib.mjs";

const NO_BUILD = process.argv.includes("--no-build");

function bundleSizes() {
  const dist = join(APP_DIR, "dist", "assets");
  const files = readdirSync(dist).filter((f) => /\.(js|css)$/.test(f));
  const entries = files.map((f) => {
    const buf = readFileSync(join(dist, f));
    return {
      file: f,
      bytes: buf.length,
      gzipBytes: gzipSync(buf).length,
    };
  });
  const total = (k) => entries.reduce((s, e) => s + e[k], 0);
  return { files: entries, totalBytes: total("bytes"), totalGzipBytes: total("gzipBytes") };
}

async function measureColdInteractive(page, baseUrl) {
  const t0 = Date.now();
  await page.goto(baseUrl, { waitUntil: "domcontentloaded" });
  const interactiveMs = await page.evaluate(async () => {
    const t0 = performance.now();
    while (!document.querySelector('[data-hs-focus-zone="commandbar"] button')) {
      await new Promise((r) => setTimeout(r, 10));
    }
    return performance.now() - t0;
  });
  const nav = await page.evaluate(() => {
    const n = performance.getEntriesByType("navigation")[0];
    return n
      ? {
          domContentLoadedMs: Math.round(n.domContentLoadedEventEnd),
          loadEventMs: Math.round(n.loadEventEnd),
          responseMs: Math.round(n.responseEnd),
        }
      : null;
  });
  return { wallMs: Date.now() - t0, interactiveMs: Math.round(interactiveMs), nav };
}

async function measureScoreRender(page, baseUrl) {
  const t0 = Date.now();
  await page.goto(`${baseUrl}/#/dev/state/scoreReady`, {
    waitUntil: "domcontentloaded",
  });
  const renderMs = await page.evaluate(async () => {
    const t0 = performance.now();
    while (!document.querySelector(".hs-score-pages svg")) {
      await new Promise((r) => setTimeout(r, 15));
      if (performance.now() - t0 > 90000) return -1;
    }
    return performance.now() - t0;
  });
  const svgBytes = await page.evaluate(
    () => document.querySelector(".hs-score-pages")?.innerHTML.length ?? 0,
  );
  const notes = await page.evaluate(
    () => document.querySelectorAll('.hs-score-pages [id^="hs-"]').length,
  );
  return { wallMs: Date.now() - t0, renderMs: Math.round(renderMs), svgBytes, scoreElements: notes };
}

async function measureViewSwitch(page) {
  await page.evaluate(() => {
    window.__hsSwitchT0 = 0;
  });
  const ms = await page.evaluate(async () => {
    const t0 = performance.now();
    const btn = [...document.querySelectorAll("button")].find(
      (b) =>
        b.textContent?.includes("設定") ||
        b.getAttribute("aria-label")?.includes("設定"),
    );
    btn?.click();
    while (!document.querySelector('[data-hs-focus-zone="settings"]')) {
      await new Promise((r) => setTimeout(r, 5));
      if (performance.now() - t0 > 10000) return -1;
    }
    return performance.now() - t0;
  });
  return Math.round(ms);
}

async function measureNoteSelect(page) {
  const ms = await page.evaluate(async () => {
    const el = document.querySelector('.hs-score-pages g.note[id^="hs-"]');
    if (!el) return -1;
    const t0 = performance.now();
    const r = el.getBoundingClientRect();
    el.dispatchEvent(
      new MouseEvent("click", {
        clientX: r.x + r.width / 2,
        clientY: r.y + r.height / 2,
        bubbles: true,
      }),
    );
    while (!document.querySelector(".hs-score-pages .hs-selected")) {
      await new Promise((r) => setTimeout(r, 2));
      if (performance.now() - t0 > 10000) return -1;
    }
    return performance.now() - t0;
  });
  return Math.round(ms);
}

async function measureSeek(page) {
  // Arm a mutation observer on the transport clock BEFORE pressing End.
  const pending = page.evaluate(() => {
    return new Promise((resolve) => {
      const clock = document.querySelector(".hs-transport__time");
      const t0 = performance.now();
      const mo = new MutationObserver(() => {
        mo.disconnect();
        resolve(performance.now() - t0);
      });
      mo.observe(clock ?? document.body, {
        characterData: true,
        childList: true,
        subtree: true,
      });
      setTimeout(() => resolve(-1), 8000);
    });
  });
  await page.keyboard.press("End");
  return Math.round(await pending);
}

async function measurePlayback(page, seconds = 4) {
  // renderStats is exposed by verovio.ts in dev builds (UI-070 hook).
  const before = await page.evaluate(
    () => window.__hsRenderStats?.renderToSVGCalls ?? null,
  );
  const result = await page.evaluate(async (secs) => {
    const score = document.querySelector(".hs-score-pages");
    const marks = [];
    const t0 = performance.now();
    const mo = new MutationObserver((muts) => {
      for (const m of muts) {
        if (
          m.type === "attributes" &&
          m.attributeName === "class" &&
          m.target.classList?.contains("hs-active")
        ) {
          marks.push(performance.now() - t0);
        }
      }
    });
    if (score) {
      mo.observe(score, {
        attributes: true,
        attributeFilter: ["class"],
        subtree: true,
      });
    }
    await new Promise((r) => setTimeout(r, secs * 1000));
    mo.disconnect();
    const heap = performance.memory
      ? Math.round(performance.memory.usedJSHeapSize / 1048576)
      : null;
    return {
      highlightUpdates: marks.length,
      firstMarkMs: marks.length ? Math.round(marks[0]) : null,
      intervals: marks.slice(1).map((t, i) => Math.round(t - marks[i])),
      heapMB: heap,
    };
  }, seconds);
  const after = await page.evaluate(
    () => window.__hsRenderStats?.renderToSVGCalls ?? null,
  );
  return {
    ...result,
    renderToSVGCallsDuringPlayback:
      before != null && after != null ? after - before : null,
  };
}

async function main() {
  const dist = join(APP_DIR, "dist", "index.html");
  if (!NO_BUILD || !existsSync(dist)) {
    console.log("building production bundle…");
    const b = spawn(process.execPath, [join(APP_DIR, "node_modules/vite/bin/vite.js"), "build"], {
      cwd: APP_DIR,
      stdio: "inherit",
    });
    await new Promise((res, rej) =>
      b.on("exit", (c) => (c === 0 ? res() : rej(new Error(`build exit ${c}`)))),
    );
  }

  const report = {
    tool: "ui-070-measure",
    timestamp: new Date().toISOString(),
    bundle: bundleSizes(),
  };

  /* ---- Phase A: production bundle, cold interactive ---- */
  const preview = startVitePreview();
  try {
    await waitForServer(preview.url);
    const { browser } = await launchBrowser();
    try {
      const page = await newPage(browser, { width: 1920, height: 1080 });
      report.coldInteractive = await measureColdInteractive(page, preview.url);
      console.log("cold interactive:", report.coldInteractive);
      report.heapProdMB = await page.evaluate(() =>
        performance.memory
          ? Math.round(performance.memory.usedJSHeapSize / 1048576)
          : null,
      );
      await page.close();
    } finally {
      await browser.close();
    }
  } finally {
    preview.proc.kill();
  }

  /* ---- Phase B: dev server, state-dependent measurements ---- */
  const dev = startViteDev(1470);
  try {
    await waitForServer(dev.url);
    const { browser } = await launchBrowser();
    try {
      const page = await newPage(browser, { width: 1920, height: 1080 });

      report.scoreRender = await measureScoreRender(page, dev.url);
      console.log("score render:", report.scoreRender);

      // Back to audioReady for view-switch / heap baseline.
      await page.goto(`${dev.url}/#/dev/state/audioReady`, {
        waitUntil: "domcontentloaded",
      });
      await settle(page, 400);
      report.viewSwitchMs = await measureViewSwitch(page);
      console.log("view switch:", report.viewSwitchMs, "ms");
      // Back to workspace.
      await page.evaluate(() => {
        [...document.querySelectorAll("button")]
          .find((b) => b.textContent?.includes("戻る"))
          ?.click();
      });
      await settle(page);

      // Score-dependent measurements.
      await page.goto(`${dev.url}/#/dev/state/scoreReady`, {
        waitUntil: "domcontentloaded",
      });
      await waitForScore(page);

      report.noteSelectMs = await measureNoteSelect(page);
      console.log("note select:", report.noteSelectMs, "ms");

      report.seekMs = await measureSeek(page);
      console.log("seek latency:", report.seekMs, "ms");

      await page.keyboard.press("Space");
      report.playback = await measurePlayback(page, 4);
      console.log("playback:", JSON.stringify(report.playback));
      await page.keyboard.press("Space");
    } finally {
      await browser.close();
    }
  } finally {
    dev.proc.kill();
  }

  const file = outPath(`perf-${Date.now()}.json`);
  writeJson(file, report);
  console.log(`\nwrote ${file}`);
  console.log(JSON.stringify(report, null, 2));
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

/**
 * Debug helper: pixel-diff two PNGs using a real browser canvas decode.
 *
 *   node scripts/ui070/pngdiff.mjs <golden.png> <candidate.png>
 *
 * Prints the differing-pixel count (summed RGB delta > 24) and bounding
 * box — use it to see whether a `ui070:matrix:check` DIFF is real layout
 * change or compositor noise.
 */
import { findBrowser, pixelDiffPng } from "./lib.mjs";
import puppeteer from "puppeteer-core";
import { existsSync } from "node:fs";

const [a, b] = process.argv.slice(2);
if (!a || !b || !existsSync(a) || !existsSync(b)) {
  console.error("usage: node scripts/ui070/pngdiff.mjs <a.png> <b.png>");
  process.exit(1);
}
const browser = await puppeteer.launch({
  executablePath: findBrowser(process.env.HS_BROWSER ?? "chrome"),
  headless: true,
  args: ["--no-sandbox"],
});
try {
  const page = await browser.newPage();
  console.log(JSON.stringify(await pixelDiffPng(page, a, b)));
} finally {
  await browser.close();
}

/**
 * @vitest-environment jsdom
 *
 * UI-070 §6/§8 accessibility gate — mounts the real shell in jsdom for
 * every reachable screen state and runs the shared audit core
 * (scripts/ui070/a11y-core.mjs — the same audit the puppeteer gates run
 * inside real Chromium):
 *
 * - accessible name on every interactive element;
 * - Japanese names (canonical UI language);
 * - role widgets keyboard-focusable;
 * - named regions/zones (data-hs-focus-zone, role=region/toolbar/dialog);
 * - color-independence (badges/stage items carry text, not color alone).
 */

import { act } from "react";
import { createRoot, type Root } from "react-dom/client";
import { afterEach, describe, expect, it } from "vitest";
import { auditAccessibility } from "../../scripts/ui070/a11y-core.mjs";
import App from "../App";
import type { ScreenState } from "../workspace/screen";
import { installJsdomStubs } from "./testEnv";

// React 18.3: act() reads this flag to enable the testing behavior.
(globalThis as Record<string, unknown>).IS_REACT_ACT_ENVIRONMENT = true;
installJsdomStubs();

let root: Root | null = null;
let host: HTMLDivElement | null = null;

async function mount(hash?: string): Promise<void> {
  window.location.hash = hash ?? "";
  host = document.createElement("div");
  document.body.appendChild(host);
  root = createRoot(host);
  await act(async () => {
    root!.render(<App />);
  });
  // Let async effects (score document load, transport snapshot) settle.
  await act(async () => {
    await new Promise((r) => setTimeout(r, 50));
  });
}

afterEach(async () => {
  if (root) {
    await act(async () => {
      root!.unmount();
    });
  }
  root = null;
  host?.remove();
  host = null;
  document.body.innerHTML = "";
  window.location.hash = "";
});

function formatViolations(report: ReturnType<typeof auditAccessibility>) {
  return report.violations
    .map((v) => `[${v.rule}] ${v.target} — ${v.detail}`)
    .join("\n");
}

const STATES: readonly { hash: string; label: ScreenState }[] = [
  { hash: "", label: "empty" },
  { hash: "#/dev/state/openingAudio", label: "openingAudio" },
  { hash: "#/dev/state/audioReady", label: "audioReady" },
  { hash: "#/dev/state/audioError", label: "audioError" },
  { hash: "#/dev/state/sourceMissing", label: "sourceMissing" },
  { hash: "#/dev/state/transcribing", label: "transcribing" },
  { hash: "#/dev/state/transcriptionError", label: "transcriptionError" },
];

describe("accessibility audit — shell screen states", () => {
  it.each(STATES)("$label: zero violations", async ({ hash, label }) => {
    await mount(hash);
    const report = auditAccessibility(document.body);
    expect(report.stats.interactive).toBeGreaterThan(0);
    expect(
      report.violations,
      `${label} violations:\n${formatViolations(report)}`,
    ).toEqual([]);
  });

  // NOTE: scoreReady/reviewing/exporting mount the Verovio WASM renderer,
  // which never initializes under jsdom — those states are audited inside
  // real Chromium by scripts/ui070/capture-matrix.mjs (the same
  // auditAccessibility function injected via page.evaluate).

  it("every state exposes a live region for status announcements", async () => {
    await mount();
    const report = auditAccessibility(document.body);
    expect(report.stats.liveRegions).toBeGreaterThanOrEqual(1);
  });
});

/**
 * @vitest-environment jsdom
 *
 * UI-070 §6 color-independence gate: status and review signaling must pair
 * color with a text label or a glyph — never color alone. Checks the badge
 * components render text + icon for every tone/status, and that the score
