  { fg: "--hs-text-secondary", bg: "--hs-surface-app", kind: "text" },
  { fg: "--hs-text-secondary", bg: "--hs-surface-panel", kind: "text" },
  { fg: "--hs-text-secondary", bg: "--hs-surface-elevated", kind: "text" },
  { fg: "--hs-text-muted", bg: "--hs-surface-app", kind: "text" },
